// AUTO-GENERATED BY silc — DO NOT EDIT
/** Particle system for visual effects triggered by signals. */

import { Mesh, MeshBuilder, StandardMaterial, Color3 } from "@babylonjs/core";
import type { BabylonHandles } from "../adapters/babylonScene.ts";
import type { Resources } from "../kernel/resources.ts";
import type { SignalBus } from "../kernel/signals.ts";
import type { GameSystem } from "../kernel/systems.ts";
import type { World } from "../kernel/world.ts";

export type ParticleEmitterComp = {
  id: string;
  preset?: "burst" | "sparkle" | "debris" | "dust" | "trail";
  count?: number;
  speed?: number;
  spread?: number;
  lifetime?: number;
  gravity?: number;
  color?: string;
  onTrigger?: string;
};

type Particle = {
  mesh: Mesh;
  vx: number;
  vy: number;
  vz: number;
  life: number;
  maxLife: number;
  gravity: number;
};

const PRESETS: Record<string, Partial<ParticleEmitterComp>> = {
  burst: { count: 8, speed: 6, spread: 360, lifetime: 0.8, gravity: 15 },
  sparkle: { count: 6, speed: 3, spread: 360, lifetime: 0.6, gravity: 0 },
  debris: { count: 4, speed: 8, spread: 180, lifetime: 1.2, gravity: 25 },
  dust: { count: 5, speed: 2, spread: 120, lifetime: 0.5, gravity: 2 },
  trail: { count: 3, speed: 1, spread: 30, lifetime: 0.4, gravity: 0 },
};

const activeParticles: Particle[] = [];
const emitterRegistry = new Map<string, ParticleEmitterComp>();

export function createParticleSystem(
  world: World,
  handles: BabylonHandles,
  resources: Resources,
  signals: SignalBus,
): GameSystem {
  return {
    name: "particles",
    order: 70,
    init() {
      // Register emitters from manifest
      const emitters = resources.manifest.particleEmitters ?? [];
      for (const emitter of emitters) {
        emitterRegistry.set(emitter.id, emitter);

        // Set up signal listener if onTrigger is specified
        if (emitter.onTrigger) {
          signals.connect(emitter.onTrigger, (data) => {
            const { x, y, z } = (data ?? {}) as { x?: number; y?: number; z?: number };
            spawnParticles(handles, emitter, x ?? 0, y ?? 0, z ?? 0);
          });
        }
      }

      // Also register entity-level emitters
      for (const [id, raw] of world.query("particleEmitter")) {
        const emitter = raw as ParticleEmitterComp;
        emitterRegistry.set(emitter.id, emitter);

        if (emitter.onTrigger) {
          signals.connect(emitter.onTrigger, (data) => {
            const { x, y, z } = (data ?? {}) as { x?: number; y?: number; z?: number };
            // Use entity position if no position in signal
            const pos = world.worldPosition(id);
            spawnParticles(
              handles,
              emitter,
              x ?? pos.x,
              y ?? pos.y,
              z ?? pos.z,
            );
          });
        }
      }

      // Listen for common game signals
      signals.connect("block_break", (data) => {
        const { x, y, z } = data as { x: number; y: number; z: number };
        const emitter = emitterRegistry.get("debris") ?? {
          id: "debris",
          preset: "debris",
          color: "#8b4513",
        };
        spawnParticles(handles, emitter, x, y, z);
      });

      signals.connect("collected", (data) => {
        const { x, y, z, kind } = (data ?? {}) as { x?: number; y?: number; z?: number; kind?: string };
        if (kind === "coin" || kind === "gem") {
          const emitter = emitterRegistry.get("sparkle") ?? {
            id: "sparkle",
            preset: "sparkle",
            color: "#ffd700",
          };
          spawnParticles(handles, emitter, x ?? 0, y ?? 0, z ?? 0);
        }
      });

      signals.connect("enemy_stomped", (data) => {
        const { x, y, z } = (data ?? {}) as { x?: number; y?: number; z?: number };
        const emitter = emitterRegistry.get("dust") ?? {
          id: "dust",
          preset: "dust",
          color: "#cccccc",
        };
        spawnParticles(handles, emitter, x ?? 0, y ?? 0, z ?? 0);
      });
    },
    update(ctx) {
      // Update active particles
      for (let i = activeParticles.length - 1; i >= 0; i--) {
        const p = activeParticles[i];
        p.life -= ctx.dt;

        if (p.life <= 0) {
          p.mesh.dispose();
          activeParticles.splice(i, 1);
          continue;
        }

        // Apply velocity and gravity
        p.vy -= p.gravity * ctx.dt;
        p.mesh.position.x += p.vx * ctx.dt;
        p.mesh.position.y += p.vy * ctx.dt;
        p.mesh.position.z += p.vz * ctx.dt;

        // Fade out
        const alpha = p.life / p.maxLife;
        p.mesh.visibility = alpha;

        // Shrink slightly
        const scale = 0.5 + alpha * 0.5;
        p.mesh.scaling.setAll(scale);
      }
    },
  };
}

function spawnParticles(
  handles: BabylonHandles,
  emitter: ParticleEmitterComp,
  x: number,
  y: number,
  z: number,
): void {
  // Merge preset defaults
  const preset = emitter.preset ? PRESETS[emitter.preset] : {};
  const count = emitter.count ?? preset.count ?? 8;
  const speed = emitter.speed ?? preset.speed ?? 5;
  const spread = emitter.spread ?? preset.spread ?? 360;
  const lifetime = emitter.lifetime ?? preset.lifetime ?? 1;
  const gravity = emitter.gravity ?? preset.gravity ?? 10;
  const colorHex = emitter.color ?? "#ffffff";

  // Parse color
  const hex = colorHex.replace("#", "");
  const r = parseInt(hex.substring(0, 2), 16) / 255;
  const g = parseInt(hex.substring(2, 4), 16) / 255;
  const b = parseInt(hex.substring(4, 6), 16) / 255;

  const spreadRad = (spread * Math.PI) / 180;
  const halfSpread = spreadRad / 2;

  for (let i = 0; i < count; i++) {
    // Random direction within spread cone (upward bias)
    const angle = Math.random() * spreadRad - halfSpread;
    const upAngle = Math.PI / 2 + (Math.random() - 0.5) * 0.5; // Mostly upward

    const vx = Math.cos(angle) * Math.sin(upAngle) * speed * (0.5 + Math.random() * 0.5);
    const vy = Math.cos(upAngle) * speed * (0.5 + Math.random() * 0.5) + speed * 0.5;
    const vz = Math.sin(angle) * Math.sin(upAngle) * speed * (0.5 + Math.random() * 0.5) * 0.3;

    // Create particle mesh
    const mesh = MeshBuilder.CreateBox(
      `particle_${Date.now()}_${i}`,
      { size: 0.15 },
      handles.scene,
    );
    mesh.position.set(x + (Math.random() - 0.5) * 0.2, y, z + (Math.random() - 0.5) * 0.2);
    mesh.isPickable = false;

    // Create material
    const mat = new StandardMaterial(`particle_mat_${Date.now()}_${i}`, handles.scene);
    mat.disableLighting = true;
    mat.emissiveColor = new Color3(r, g, b);
    mesh.material = mat;

    activeParticles.push({
      mesh,
      vx,
      vy,
      vz,
      life: lifetime * (0.7 + Math.random() * 0.3),
      maxLife: lifetime,
      gravity,
    });
  }
}

/** Manually trigger a particle emitter by ID. */
export function triggerEmitter(
  handles: BabylonHandles,
  emitterId: string,
  x: number,
  y: number,
  z: number,
): void {
  const emitter = emitterRegistry.get(emitterId);
  if (emitter) {
    spawnParticles(handles, emitter, x, y, z);
  }
}

/** Clean up all active particles. */
export function disposeParticles(): void {
  for (const p of activeParticles) {
    p.mesh.dispose();
  }
  activeParticles.length = 0;
}
